<?php
namespace App\Controller\Api;
use App\Entity\Post;use App\Repository\PostRepository;use Symfony\Bundle\FrameworkBundle\Controller\AbstractController;use Symfony\Component\HttpFoundation\JsonResponse;use Symfony\Component\Routing\Attribute\Route;
#[Route('/api/avisos')]final class PostController extends AbstractController{#[Route('',name:'api_aviso_index',methods:['GET'])]public function index(PostRepository $r):JsonResponse{return$this->json(array_map($this->normalize(...),$r->findPublicados()));}#[Route('/{slug}',name:'api_aviso_show',methods:['GET'])]public function show(string $slug,PostRepository $r):JsonResponse{$p=$r->findOneBy(['slug'=>$slug,'publico'=>true,'status'=>Post::STATUS_PUBLICADO]);if(!$p)throw$this->createNotFoundException();return$this->json($this->normalize($p,true));}private function normalize(Post $p,bool $full=false):array{$d=['id'=>$p->getId(),'titulo'=>$p->getTitulo(),'slug'=>$p->getSlug(),'resumo'=>$p->getResumo(),'fixado'=>$p->isFixado(),'prioridade'=>$p->getPrioridade(),'publicadoEm'=>$p->getPublicadoEm()?->format(DATE_ATOM),'autor'=>$p->getAutor()?->getNome()];if($full)$d['conteudo']=$p->getConteudo();return$d;}}
